import { ProductWithQuantity } from "@/core/types/state/group-admission/group-admission-types";
import styles from "./product-text-block.module.less";
import { useTranslation } from "react-i18next";
import { useShowHighEntranceWarning } from "@/core/hooks";
import { CurrencyHelper } from "@/core/helpers";
import { multipleClassNames } from "@/core/helpers/string-helper";

const ProductTextBlock = ({
  product,
  productName,
  soldOutProduct,
  highEntrance,
  shortDescription,
}: {
  product: ProductWithQuantity;
  productName: string;
  soldOutProduct: boolean;
  highEntrance: ReturnType<typeof useShowHighEntranceWarning>;
  shortDescription?: string;
}) => {
  const { t } = useTranslation();

  const shouldDisplayAsDisabled = soldOutProduct || highEntrance.showWarning;

  const HeadlineElement = shouldDisplayAsDisabled ? "s" : "div";

  return (
    <div className={styles.textBlockWrapper}>
      <HeadlineElement className={multipleClassNames(styles.textBlockHeadline, "body-m bold")}>
        <p className={styles.productName}>{productName}</p>
        <p className={styles.productPrice} data-contentful-label-id="currencyPerUnit">
          {CurrencyHelper.formatToSek(product.price)}
          {t("currencyPerUnit")}
        </p>
      </HeadlineElement>
      {shouldDisplayAsDisabled && (
        <p
          style={{ fontStyle: "italic" }}
          className={styles.productPickerDescription}
          data-contentful-label-id={
            highEntrance.showWarning ? "selectTicketStepHighEntrancePassed" : "selectTicketStepSoldOutProduct"
          }
        >
          {highEntrance.showWarning
            ? t("selectTicketStepHighEntrancePassed", [highEntrance.highEntranceStart])
            : t("selectTicketStepSoldOutProduct")}
        </p>
      )}
      {!shouldDisplayAsDisabled && shortDescription && (
        <p className={styles.productPickerDescription}>{shortDescription}</p>
      )}
      {!shouldDisplayAsDisabled && product.productMetadata.numberOfJetPassIncluded > 0 && (
        <p
          style={{ fontStyle: "italic" }}
          className={["p_tiny", styles.productPickerJetpasses].join(" ")}
          data-contentful-label-id="selectTicketStepJetpassesIncluded"
        >
          {product.productMetadata.numberOfJetPassIncluded} {t("selectTicketStepJetpassesIncluded")}
        </p>
      )}
    </div>
  );
};

export default ProductTextBlock;
