import { useProduct } from "@/core/hooks/product-hooks";
import { ProductWithQuantity } from "@/core/types/state/group-admission/group-admission-types";
import QuantityPicker from "../quantity-picker/quantity-picker";

const ProductPicker = ({
  product,
  totalQuantityLeft,
  selectedDate,
  changeQuantityOfProduct,
}: {
  product: ProductWithQuantity;
  totalQuantityLeft: number;
  selectedDate: Date;
  changeQuantityOfProduct: (quantity: number, product: ProductWithQuantity) => void;
}) => {
  const normalizedProduct = useProduct(product.productId);

  const onChangeQuantity = (quantity: number) => {
    changeQuantityOfProduct(quantity, product);
  };

  return (
    <QuantityPicker
      product={product}
      normalizedProduct={normalizedProduct}
      currentQuantity={product.quantity}
      selectedDate={selectedDate}
      onChangeQuantity={onChangeQuantity}
      totalQuantityLeft={totalQuantityLeft}
    />
  );
};

export default ProductPicker;
