import { useMemo } from "react";
import { createDate, DateHelper, TodayHelper } from "../helpers";
import { OpeningHoursService } from "../services";
import { range, sortBy } from "lodash-es";
import { OpeningHoursItem } from "@parksandresorts/webapiproxy-types";
import { useQuery } from "@tanstack/react-query";
import { useStaticConfigContext } from "../contexts";

type ProductWithHighEntranceData = {
  productId: number;
  template?: {
    highEntrance: boolean;
  };
  quantity: number;
};

export type IOpeningHoursHooks = {
  useOpeningHours: () => Array<OpeningHoursItem>;
  useOpeningHoursForDate: (selectedDate: Date) => OpeningHoursItem | undefined;
  useIsHighEntranceDay: (
    selectedDate: Date,
  ) => { isHighEntrance: false } | { isHighEntrance: true; highEntranceStart: string; highEntranceStop: string };
  useShowHighEntranceWarning: (
    selectedDate: Date,
    products: Array<ProductWithHighEntranceData>,
    /** Useful if the quantity should not matter when checking for if valid on high entrance days */
    ignoreQuantity?: boolean,
  ) =>
    | { showWarning: false }
    | {
        showWarning: true;
        highEntranceStart: string;
        highEntranceStop: string;
        productsNotValidDuringHighEntrance: Array<ProductWithHighEntranceData>;
      };
  useIsParkOpenNow: () => boolean;
  useIsSplitDay: (selectedDate: Date) => boolean;
  openDatesFromOpeningHours: (
    openingHours: ReturnType<typeof useOpeningHours>,
    padding?: number,
  ) => {
    startDate?: Date;
    endDate?: Date;
    disabledDates: (d: Date) => boolean;
  };
};

export const useOpeningHours = () => {
  const { openingHours } = useStaticConfigContext();

  const openingTimeResult = useQuery({
    queryKey: ["opening-hours"],
    queryFn: () => OpeningHoursService.getAllDates(),
    initialData: openingHours ?? [],
  });

  const openingTime = openingTimeResult.data;

  return openingTime;
};

export const useOpeningHoursForDate: IOpeningHoursHooks["useOpeningHoursForDate"] = (selectedDate) => {
  const allOpeningHours = useOpeningHours();

  // used to make sure memoization only re-evaluates when the actual date changes, not time of day
  const selectedDateString = selectedDate && DateHelper.toStringYYYYMMDD(selectedDate);

  return useMemo(() => {
    if (!selectedDateString) return undefined;

    return allOpeningHours?.find(
      (item) =>
        item.areaOpeningHours?.some(
          (area) => item && area.areaId === 1 && DateHelper.isEqualYYYYMMDD(area.dateFrom, selectedDateString),
        ),
    );
  }, [selectedDateString, allOpeningHours]);
};

export const useIsHighEntranceDay: IOpeningHoursHooks["useIsHighEntranceDay"] = (selectedDate) => {
  const openingHoursForDate = useOpeningHoursForDate(selectedDate);

  const { highEntranceStart, highEntranceStop } = openingHoursForDate ?? {};
  const isHighEntrance = highEntranceStart && highEntranceStop && highEntranceStart !== highEntranceStop;
  return isHighEntrance
    ? {
        isHighEntrance,
        highEntranceStart: highEntranceStart.substring(0, "hh:mm".length),
        highEntranceStop: highEntranceStop.substring(0, "hh:mm".length),
      }
    : { isHighEntrance: false };
};

export const HIGH_ENTRANCE_BLOCKING_BUFFER_MINUTES = 5;

export const useShowHighEntranceWarning: IOpeningHoursHooks["useShowHighEntranceWarning"] = (
  selectedDate,
  products,
  ignoreQuantity = false,
) => {
  const isHighEntranceDay = useIsHighEntranceDay(selectedDate);

  if (!isHighEntranceDay.isHighEntrance) return { showWarning: false };

  const productsNotValidDuringHighEntrance = products
    .map((p) => ({
      ...p,
      quantity: ignoreQuantity ? 1 : p.quantity,
    }))
    .filter((p) => p.template && !p.template.highEntrance && p.quantity > 0);

  const atLeastOneProductNotValidDuringHighEntrance = productsNotValidDuringHighEntrance.length > 0;
  if (!atLeastOneProductNotValidDuringHighEntrance) return { showWarning: false };
  return {
    showWarning: true,
    highEntranceStart: isHighEntranceDay.highEntranceStart,
    highEntranceStop: isHighEntranceDay.highEntranceStop,
    productsNotValidDuringHighEntrance,
  };
};

export const useIsParkOpenNow = () => {
  const now = TodayHelper.getNow();
  const todaysOpeningHours = useOpeningHoursForDate(now);
  if (!todaysOpeningHours) return false;

  const opens = createDate(todaysOpeningHours?.opens);
  const closing = createDate(todaysOpeningHours?.closing);
  return DateHelper.isDateInDateSpan(now, opens, closing);
};

export const useIsSplitDay: IOpeningHoursHooks["useIsSplitDay"] = (selectedDate) => {
  const todaysOpeningHours = useOpeningHoursForDate(selectedDate);
  if (!todaysOpeningHours) return false;

  const sortedPasses = sortBy(todaysOpeningHours.passes, (pass) => new Date(pass.from).getTime());
  return sortedPasses.some(
    (pass, index) => index > 0 && new Date(pass.from).getTime() > new Date(sortedPasses[index - 1].to).getTime(),
  );
};

/**
 * Returns properties that interprets opening hours as dates, with optional padding
 *
 * The padding is used when, for example, you want Fridays and Mondays to appear as open when the park is only open on
 * Saturday and Sunday (which would be achieved with `padding = 1`). This is used for the campsite booking.
 */
export function openDatesFromOpeningHours(
  openingHours: ReturnType<typeof useOpeningHours>,
  padding = 0,
): {
  startDate?: Date;
  endDate?: Date;
  disabledDates: (d: Date) => boolean;
} {
  const asDates = openingHours.map((o) => createDate(o.opens));
  const paddedDates = asDates
    .flatMap((date) => [
      date,
      ...range(padding)
        .map((d) => d + 1)
        .flatMap((offset) => [DateHelper.addDays(date, offset), DateHelper.addDays(date, -offset)]),
    ])
    .sort((a, b) => a.valueOf() - b.valueOf());

  const startDate = paddedDates[0];
  const endDate = paddedDates[paddedDates.length - 1] ?? startDate;

  const setOfDates = new Set(paddedDates.map((d) => DateHelper.toStringYYYYMMDD(d)));

  return { startDate, endDate, disabledDates: (d) => !setOfDates.has(DateHelper.toStringYYYYMMDD(d)) };
}
