// @ts-strict-ignore
import styles from "./select-ticket.module.less";
import { DateHelper, GroupAdmissionHelper, isNonEmptyArray, isTruthy } from "@/core/helpers";
import { EntryVariant, Product, VisitorCategory } from "@/core/types/services/purchase-flow-service-types";
import {
  ActionType,
  CategoryListProps,
  GroupAdmissionState,
  Guest,
  ProductWithQuantity,
  SelectTicketCategoriesList,
  Step,
  StepProps,
  VisitDate,
} from "@/core/types/state/group-admission/group-admission-types";
import { useTranslation } from "react-i18next";
import { uniqBy } from "lodash-es";
import { useEffect, useState, useMemo } from "react";
import useFocus from "@/core/hooks/use-focus";
import { AnimatePresence } from "framer-motion";
import { useStepWarning } from "../../step-warning/step-warning";
import { corei18n } from "@/core/labels/i18n";
import { IOpeningHoursHooks } from "@/core/hooks";
import { DialogModal } from "@/core/components/primitives/dialog-modal/dialog-modal";
import CategoryTicketSelector from "./components/category-ticket-selector/category-ticket-selector";
import { ButtonRow } from "../../components/button-row";
import { ProductBlockFragment as AdditionalProduct } from "@/core/types";
import { NormalizedProduct, useProducts } from "@/core/hooks/product-hooks";
import { WebshopProductType } from "@parksandresorts/webapiproxy-types";

type SelectTicketProps = {
  isActive: boolean;
  visitorCategories: Map<VisitorCategory["id"], VisitorCategory>;
  selectedAmountPerCategory: GroupAdmissionState["quantity"];
  stepWrapperRef: HTMLElement;
  firstDateInSelectedDates: VisitDate;
  selectedDateProducts: Array<Product>;
  variantsForSelectedDate: Array<EntryVariant["id"]>;
  isNextStepCompleted: boolean;
  guests: Array<Guest>;
  additionalProductsAdult?: Array<AdditionalProduct>;
  additionalProductsChild?: Array<AdditionalProduct>;
  additionalProductsSenior?: Array<AdditionalProduct>;
  additionalProductsInfant?: Array<AdditionalProduct>;
  useOpeningHoursForDate: IOpeningHoursHooks["useOpeningHoursForDate"];
} & StepProps;

const getCategoryQuantities = (category: CategoryListProps) => {
  return [...category.productsByVariant]
    .flatMap(([, products]) => products.map((p) => p.quantity))
    .reduce((a, b) => a + b, 0);
};

const convertTypeToName = (type: CategoryListProps["type"], quantity: number) => {
  switch (type) {
    case "Adult":
      return corei18n.t("adult", { count: quantity });
    case "Child":
      return corei18n.t("child", { count: quantity });
    case "Elderly":
      return corei18n.t("elderly", { count: quantity });
    case "Baby":
      return corei18n.t("baby", { count: quantity });
    default:
      return type;
  }
};

const getQuantitiesForNonCompletedCategories = (categoriesList: SelectTicketCategoriesList) => {
  return [...categoriesList]
    .map(([, category]) => {
      const categoryQuantities = getCategoryQuantities(category);

      if (categoryQuantities !== category.selectedQuantityOfCategoryInGroup) {
        const quantityOfCategoryLeft = category.selectedQuantityOfCategoryInGroup - categoryQuantities;
        return corei18n.t("selectTicketStepYouHaveNotChosenTicketsFor", {
          0: convertTypeToName(category.type, quantityOfCategoryLeft),
        });
      }
      return null;
    })
    .filter((item) => item !== null);
};

const allCategoriesAreCompleted = (categoriesList: SelectTicketCategoriesList) => {
  return [...categoriesList].every(([, category]) => {
    const categoryQuantities = getCategoryQuantities(category);
    return categoryQuantities === category.selectedQuantityOfCategoryInGroup;
  });
};

/**
 * Compares the dateSlotIds of the guests and the categoriesList
 */
const isGuestsProductsSameAsCategoriesList = (guests: Array<Guest>, categoriesList: SelectTicketCategoriesList) => {
  const guestCompareKeys = guests.map((guest) => {
    const dateSlotId = guest.admissionProduct?.dateSlotId;
    const productId = guest.admissionProduct.id;
    return `${dateSlotId}-${productId}`;
  });

  const categoriesListCompareKeys: Array<string> = [];
  for (const [, category] of categoriesList) {
    for (const [, products] of category.productsByVariant) {
      for (const product of products) {
        if (product.quantity > 0) {
          for (let i = 0; i < product.quantity; i++) {
            const dateSlotId = product.dateSlot?.dateSlotId;
            const productId = product.productId;
            categoriesListCompareKeys.push(`${dateSlotId}-${productId}`);
          }
        }
      }
    }
  }

  guestCompareKeys.sort();
  categoriesListCompareKeys.sort();

  return (
    guestCompareKeys.length === categoriesListCompareKeys.length &&
    guestCompareKeys.every((id, i) => id === categoriesListCompareKeys[i])
  );
};

/**
 * Compares the total number of jetpasses included in the guests' selected tickets
 * and the total number of jetpasses included in the updated selected categories
 */
const areUpdatedJetpassesDifferent = (guests: Array<Guest>, updatedSelectedCategories: SelectTicketCategoriesList) => {
  const getTotalIncludedJetpasses = (guests: Array<Guest>) => {
    return guests
      .map((guest) => guest.admissionProduct.numberOfJetpassIncluded)
      .reduce((total, includedJetpasses) => total + includedJetpasses, 0);
  };

  const getTotalIncludedJetpassesInCategories = (categoriesList: SelectTicketCategoriesList) => {
    const calculateJetpassesForProduct = (product: ProductWithQuantity) => {
      return product.productMetadata.numberOfJetPassIncluded * product.quantity;
    };

    const calculateJetpassesForProducts = (products: Array<ProductWithQuantity>) => {
      return products
        .filter((product) => product.quantity > 0)
        .reduce((total, product) => total + calculateJetpassesForProduct(product), 0);
    };

    const calculateJetpassesForCategory = (category: CategoryListProps) => {
      if (category.productsByVariant) {
        const allProducts = [...category.productsByVariant].flatMap(([, products]) => products);
        return calculateJetpassesForProducts(allProducts);
      }
      return 0;
    };

    const totalJetpasses = [...categoriesList].reduce(
      (total, [, category]) => total + calculateJetpassesForCategory(category),
      0,
    );

    return totalJetpasses;
  };

  const alreadyIncludedJetpasses = getTotalIncludedJetpasses(guests);
  const includedJetpassesInTotalCategoriesChange = getTotalIncludedJetpassesInCategories(updatedSelectedCategories);

  return alreadyIncludedJetpasses ? includedJetpassesInTotalCategoriesChange !== alreadyIncludedJetpasses : false;
};

/**
 * We need to filter out products that are not of type "Standard" and does not contain the correct visitor category.
 * It is important to note that this function sets default mock values for certain properties since the additional products don't have all the necessary data available.
 */
const getAdditionalProductsWithQuantity = (
  productsById: ReadonlyMap<number, Exclude<NormalizedProduct, { glkProduct: undefined }>>,
  selectedDate: Date,
  additionalProductsAdult?: Array<AdditionalProduct>,
  additionalProductsChild?: Array<AdditionalProduct>,
  additionalProductsSenior?: Array<AdditionalProduct>,
  additionalProductsInfant?: Array<AdditionalProduct>,
) => {
  const mapProducts = (
    additionalProducts: Array<AdditionalProduct> | undefined,
    visitorCategory: VisitorCategory["id"],
  ) => {
    if (!additionalProducts) return [];
    return additionalProducts
      .map((additionalProduct) => {
        if (!additionalProduct.productData?.glkId) return undefined;
        const product = productsById.get(Number(additionalProduct.productData.glkId));
        if (product?.glkProduct.productType !== WebshopProductType.STANDARD) return undefined;
        return {
          ...additionalProduct,
          price: product.glkProduct.priceIncludingVat,
          productId: product.productId,
          quantity: 0,
          timePassRequired: false,
          dateSlot: {
            dateSlotId: undefined,
            date: DateHelper.toStringTimeYYYYMMDDHHMM(selectedDate),
            quantity: 999,
          },
          productMetadata: {
            entryVariant: "Additional",
            visitorCategory,
            numberOfJetPassIncluded: product.glkProduct.metadata?.jetPassPerVisitLimit ?? 0,
            priceLevel: 0,
            timeLimits: undefined,
            autoSelectTimeslot: false,
          },
        } satisfies ProductWithQuantity;
      })
      .filter(isTruthy);
  };

  return {
    Adult: mapProducts(additionalProductsAdult, "Adult"),
    Child: mapProducts(additionalProductsChild, "Child"),
    Elderly: mapProducts(additionalProductsSenior, "Elderly"),
    Baby: mapProducts(additionalProductsInfant, "Baby"),
  };
};

const SelectTicket = ({
  onClickBack,
  stepIndex,
  isActive,
  visitorCategories,
  selectedAmountPerCategory,
  firstDateInSelectedDates,
  selectedDateProducts,
  variantsForSelectedDate,
  stepWrapperRef,
  isNextStepCompleted,
  guests,
  additionalProductsAdult,
  additionalProductsChild,
  additionalProductsSenior,
  additionalProductsInfant,
  dispatch,
}: SelectTicketProps) => {
  const [categoriesList, setCategoriesList] = useState<SelectTicketCategoriesList>(new Map());
  const [showStepWarning, setShowStepWarning] = useState(false);
  const [informationModalProps, setInformationModalProps] = useState(null);
  const [focusRef, setFocus] = useFocus<HTMLDivElement>();
  const [stepWarningBodyList, setStepWarningBodyList] = useState<Array<string>>([]);

  const { t } = useTranslation();
  const { productsById: additionalProducts } = useProducts(
    [additionalProductsAdult, additionalProductsChild, additionalProductsSenior, additionalProductsInfant]
      .filter(isNonEmptyArray)
      .flatMap((products) => products.map((p) => Number(p.productData?.glkId))),
  );

  const { scrollAndFocusOnWarning, StepWarning } = useStepWarning({
    title: "selectTicketStepWarningTitle",
    bodyText: "selectTicketStepWarningBodyText",
    bodyList: stepWarningBodyList,
  });

  const additionalProductsWithQuantity = useMemo(() => {
    if (!firstDateInSelectedDates?.date) {
      return {} as Partial<ReturnType<typeof getAdditionalProductsWithQuantity>>;
    }
    return getAdditionalProductsWithQuantity(
      additionalProducts,
      firstDateInSelectedDates.date,
      additionalProductsAdult ?? [],
      additionalProductsChild ?? [],
      additionalProductsSenior ?? [],
      additionalProductsInfant ?? [],
    );
  }, [
    additionalProducts,
    firstDateInSelectedDates?.date,
    additionalProductsAdult,
    additionalProductsChild,
    additionalProductsSenior,
    additionalProductsInfant,
  ]);

  useEffect(() => {
    !isActive && setShowStepWarning(false);
  }, [isActive]);

  useEffect(() => {
    const categoriesArray: Array<CategoryListProps> = [];
    for (const [selectedCategory, selectedQuantity] of selectedAmountPerCategory) {
      if (selectedQuantity > 0) {
        const visitorCategory = visitorCategories.get(selectedCategory);

        const uniqueProductsById = uniqBy(selectedDateProducts, "productId");

        const productsByCategoryType = uniqueProductsById.filter(
          (product) => product.productMetadata.visitorCategory === selectedCategory,
        );

        // Commented out due to the fact that the most expensive product is not used in the current implementation
        // const mostExpensiveProduct =
        //   productsByCategoryType.length &&
        //   productsByCategoryType.reduce((prev, current) => {
        //     return prev.price > current.price ? prev : current;
        //   });

        // Get matching additional products for the selected category.
        const additionalForCategory = additionalProductsWithQuantity[selectedCategory] || [];

        const productsWithQuantity = productsByCategoryType.map((product) => {
          // Commented out due to the fact that the most expensive product is not used in the current implementation
          // if (product === mostExpensiveProduct) {
          //   return {
          //     ...product,
          //     quantity: value,
          //   };
          // }

          if (
            productsByCategoryType.length === 1 &&
            product.dateSlot.quantity > 0 &&
            !isNonEmptyArray(additionalForCategory) // prevent pre selected quantity when there are additional products
          ) {
            return {
              ...product,
              quantity: selectedQuantity,
            };
          } else {
            return {
              ...product,
              quantity: 0,
            };
          }
        });

        const sortedProductsByPriceOrQuantity = productsWithQuantity.sort(
          (a, b) => b.price - a.price || b.quantity - a.quantity,
        );

        const productsGroupedByVariant = GroupAdmissionHelper.getMappedProductsFromSelectedVariants(
          sortedProductsByPriceOrQuantity,
          variantsForSelectedDate,
        );

        // Add additional products to the matching category.
        if (isNonEmptyArray(additionalForCategory)) {
          const variant = additionalForCategory[0].productMetadata.entryVariant;
          // If already there, merge, otherwise set new.
          const existingAdditional = productsGroupedByVariant.get(variant) || [];
          productsGroupedByVariant.set(variant, [...existingAdditional, ...additionalForCategory]);
        }

        categoriesArray.push({
          name: visitorCategory.name,
          type: visitorCategory.id,
          selectedQuantityOfCategoryInGroup: selectedQuantity,
          productsByVariant: productsGroupedByVariant,
          sortIndex: visitorCategory.sortIndex,
        });
      }
    }

    categoriesArray.sort((a, b) => a.sortIndex - b.sortIndex);
    const categoriesMap: SelectTicketCategoriesList = new Map(
      categoriesArray.map((category) => [category.type, category]),
    );

    setCategoriesList(categoriesMap);
  }, [
    selectedAmountPerCategory,
    selectedDateProducts,
    variantsForSelectedDate,
    visitorCategories,
    additionalProductsWithQuantity,
  ]);

  const closeDialog = () => {
    setFocus();
    setInformationModalProps(null);
  };

  const onClickStepComplete = () => {
    if (!allCategoriesAreCompleted(categoriesList)) {
      const quantitiesForNonCompletedCategories = getQuantitiesForNonCompletedCategories(categoriesList);

      if (JSON.stringify(quantitiesForNonCompletedCategories) !== JSON.stringify(stepWarningBodyList)) {
        setStepWarningBodyList(quantitiesForNonCompletedCategories);
      }

      setShowStepWarning(true);
      scrollAndFocusOnWarning();
    } else {
      setStepWarningBodyList([]);
      setShowStepWarning(false);

      const doesGuestsProductsMatchCategoriesList = isGuestsProductsSameAsCategoriesList(guests, categoriesList);

      if (!doesGuestsProductsMatchCategoriesList) {
        dispatch({ type: ActionType.SELECT_TICKET, payload: { selectedTickets: categoriesList } });
      }

      GroupAdmissionHelper.scrollAndCompleteStep(stepWrapperRef, Step.SELECT_TICKET, dispatch, true);
    }
  };

  const onSelectCategories = (value: CategoryListProps, overrideClick?: boolean) => {
    const updatedSelectedCategories = new Map(categoriesList);
    updatedSelectedCategories.set(value.type, value);

    const hasGuestsJetpasses = guests.some((guest) => guest.admissionProduct.selectedJetpasses.length > 0);
    const hasJetpassesChanged = areUpdatedJetpassesDifferent(guests, updatedSelectedCategories);

    const shouldShowInformationModal =
      isNextStepCompleted && !overrideClick && hasGuestsJetpasses && hasJetpassesChanged;

    if (shouldShowInformationModal) {
      return setInformationModalProps({ value: value });
    }

    setCategoriesList(updatedSelectedCategories);

    if (overrideClick) {
      setFocus();
      dispatch({
        type: ActionType.SELECT_TICKET,
        payload: {
          selectedTickets: updatedSelectedCategories,
          hasSubsequentChanges: hasJetpassesChanged,
        },
      });
    }

    setInformationModalProps(null);
  };

  return (
    <div className={styles.selectTicketWrapper} ref={focusRef} tabIndex={-1}>
      <AnimatePresence mode="wait">{showStepWarning && <StepWarning />}</AnimatePresence>
      {categoriesList.size !== 0 &&
        [...categoriesList].map(([, category]) => (
          <CategoryTicketSelector
            key={category.type}
            category={category}
            onCategoryChange={onSelectCategories}
            selectedDate={firstDateInSelectedDates?.date}
          />
        ))}

      <ButtonRow stepIndex={stepIndex} onClickBack={onClickBack} onClickStepComplete={onClickStepComplete} />
      <AnimatePresence>
        {informationModalProps && (
          <DialogModal
            headingText={t("selectTicketStepDialogHeading")}
            bodyText={t("selectTicketStepDialogBodyText")}
            primaryButtonText={t("selectTicketStepDialogConfirmChange")}
            primaryButtonAction={() => onSelectCategories(informationModalProps.value, true)}
            secondaryButtonText={t("cancel")}
            secondaryButtonAction={closeDialog}
            onCloseFunction={closeDialog}
            contentfulLabelIds={{
              headingText: "selectTicketStepDialogHeading",
              bodyText: "selectTicketStepDialogBodyText",
              confirmChange: "selectTicketStepDialogConfirmChange",
              cancelChange: "cancel",
            }}
          />
        )}
      </AnimatePresence>
    </div>
  );
};

export default SelectTicket;
