import styles from "./radio-picker.module.less";
import { StyledRadioButtons } from "@/core/components/primitives/styled-radio-buttons/styled-radio-buttons";
import { RadioOption } from "@/core/components/primitives/radio-buttons/radio-buttons";
import { ProductWithQuantity } from "@/core/types/state/group-admission/group-admission-types";
import ProductTextBlock from "../product-text-block/product-text-block";
import { useProducts } from "@/core/hooks/product-hooks";
import { HIGH_ENTRANCE_BLOCKING_BUFFER_MINUTES, useShowHighEntranceWarning } from "@/core/hooks/opening-hours-hooks";
import DateHelper from "@/core/helpers/date-helper";
import { TodayHelper } from "@/core/helpers/today-helper";
import { GroupAdmissionHelper } from "@/core/helpers";

const RadioPicker = ({
  products,
  categoryName,
  selectedDate,
  selectedValue,
  changeProduct,
}: {
  products: Array<ProductWithQuantity>;
  categoryName: string;
  selectedDate: Date;
  selectedValue: string;
  changeProduct: (product: ProductWithQuantity) => void;
}) => {
  const highEntranceWarning = useShowHighEntranceWarning(selectedDate, products, true);
  const dateTimeOfHighEntrance = highEntranceWarning.showWarning
    ? DateHelper.dateWithModifiedTime(selectedDate, highEntranceWarning.highEntranceStart)
    : undefined;

  const glkIds = products.map((p) => p.productId);
  const { productsById } = useProducts(glkIds);

  const radioOptions: Array<RadioOption> = products.map((product) => {
    const normalizedProduct = productsById.get(product.productId);
    const productName = normalizedProduct?.name || product.productName;
    const soldOutProduct = product.dateSlot?.quantity === 0;
    const thisTicketNotValidOnHighEntrance =
      highEntranceWarning.showWarning &&
      highEntranceWarning.productsNotValidDuringHighEntrance.find((p) => p.productId === product.productId) !==
        undefined;

    const now = TodayHelper.getNow();
    const hasTimePassedOnDateOfVisit = dateTimeOfHighEntrance
      ? DateHelper.addMinutes(now, HIGH_ENTRANCE_BLOCKING_BUFFER_MINUTES) > dateTimeOfHighEntrance
      : false;

    //The guest should not be able to buy a ticket that is not valid on high entrance days if the time of high entrance has passed
    const shouldDisableBecauseOfHighEntrance = thisTicketNotValidOnHighEntrance && hasTimePassedOnDateOfVisit;
    return {
      label: (
        <ProductTextBlock
          product={product}
          productName={productName}
          soldOutProduct={soldOutProduct}
          highEntrance={shouldDisableBecauseOfHighEntrance ? highEntranceWarning : { showWarning: false }}
          shortDescription={normalizedProduct?.contentfulProduct?.shortDescription ?? undefined}
        />
      ),

      value: GroupAdmissionHelper.getRadioPickerValueFromProduct(product),
      disabled: soldOutProduct || shouldDisableBecauseOfHighEntrance,
    };
  });

  const onChangeProduct = (name: string, productId: string) => {
    const changedProduct = products.find((product) => product.productId === parseInt(productId));
    if (!changedProduct) return;
    changeProduct(changedProduct);
  };

  return (
    <div className={styles.radioPickerList}>
      <StyledRadioButtons
        radioItemClassName={styles.radioPickerItem}
        radioItemsWrapperClassName={styles.radioPickerItemsWrapper}
        key={categoryName}
        name={"radio-picker-" + categoryName}
        onChange={onChangeProduct}
        value={selectedValue}
        options={radioOptions}
      />
    </div>
  );
};

export default RadioPicker;
